// Classify a workflow failure so that only the failures a human can act on
// wake a human up.
//
// The Error Trigger fires for the WHOLE workflow, including failures nobody
// anticipated and failures of the schedule trigger itself. That is the
// difference between this and an error branch wired off one node: an error
// branch only catches the node you already thought to guard.

const input = $input.first().json;
const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || {};

const message = String(error.message || 'Unknown error');
const name = String(error.name || 'Error');
const description = String(error.description || '');
const httpCode = Number(error.httpCode || error.statusCode || 0);

// n8n normalises exceptions thrown inside a Code node. Verified by running it:
// `throw new TypeError('probe: simulated code defect')` arrives here as
// name="Error" (constructor name lost), message="simulated code defect
// [line 3]" (prefix moved into error.description, line suffix appended).
//
// So error.name is NOT a reliable signal for Code-node failures. The "[line N]"
// suffix is, because n8n only appends it for code it evaluated itself.
const isCodeNodeError = /\[line \d+\]/.test(message);

// Transient: the upstream had a bad moment. Retrying later is the correct
// response and paging someone at 03:00 is not.
const TRANSIENT_PATTERNS = [
  'ETIMEDOUT', 'ECONNRESET', 'ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN',
  'socket hang up', 'timeout', 'network', 'rate limit', 'too many requests'
];

const haystack = (message + ' ' + description).toLowerCase();

const looksTransient =
  TRANSIENT_PATTERNS.some(p => haystack.includes(p.toLowerCase())) ||
  httpCode === 429 ||
  (httpCode >= 500 && httpCode <= 599);

// Permanent: the workflow is broken, or the contract with the API changed.
// These do not fix themselves and every run until someone looks will fail.
const CODE_ERRORS = ['TypeError', 'ReferenceError', 'SyntaxError'];
const looksLikeCodeBug = CODE_ERRORS.includes(name) || isCodeNodeError;
const looksLikeAuth = httpCode === 401 || httpCode === 403;

let category;
let severity;

if (looksLikeCodeBug) {
  category = 'code_defect';
  severity = 'page';
} else if (looksLikeAuth) {
  category = 'auth_failure';
  severity = 'page';
} else if (httpCode >= 400 && httpCode < 500 && httpCode !== 429) {
  // A 4xx that is not rate limiting usually means the request we are sending
  // is now wrong -- a changed parameter or a removed endpoint.
  category = 'contract_changed';
  severity = 'page';
} else if (looksTransient) {
  category = 'transient';
  severity = 'log_only';
} else {
  // Unknown beats silently-assumed-transient. An unclassified failure that
  // turns out to be permanent costs a full day of pipeline.
  category = 'unclassified';
  severity = 'page';
}

return [{
  json: {
    severity,
    category,
    workflow_id: workflow.id || null,
    workflow_name: workflow.name || null,
    execution_id: execution.id || null,
    execution_url: execution.url || null,
    failed_node: execution.lastNodeExecuted || null,
    error_name: name,
    error_message: message,
    error_description: description || null,
    code_node_error: isCodeNodeError,
    http_code: httpCode || null,
    retry_of: execution.retryOf || null,
    detected_at: new Date().toISOString()
  }
}];

// Actionable failure. Emit a page payload.
//
// Not wired to Slack or PagerDuty here: that needs a credential this repo does
// not ship, and a delivery step that cannot run is worse than an explicit
// handoff. The payload below is the contract a delivery node would consume.

const a = $input.first().json;

const title = `[GTM] ${a.category} in ${a.workflow_name || 'unknown workflow'}`;
const body = [
  `Workflow : ${a.workflow_name} (${a.workflow_id})`,
  `Failed at: ${a.failed_node || 'unknown node'}`,
  `Error    : ${a.error_name}: ${a.error_message}`,
  a.http_code ? `HTTP     : ${a.http_code}` : null,
  `Execution: ${a.execution_url || a.execution_id}`,
  `Detected : ${a.detected_at}`,
  '',
  'This class of failure does not clear on its own. The next scheduled run',
  'will fail the same way until someone changes something.'
].filter(Boolean).join('\n');

return [{
  json: {
    delivery: 'page',
    channel_hint: 'oncall',
    title,
    body,
    alert: a
  }
}];

// Transient failure. Record it and stay quiet.
//
// Suppression is only safe because it is counted: a transient that recurs is
// not transient, and the repeat_window field is what a downstream check would
// use to escalate rather than swallowing the same outage nightly.

const a = $input.first().json;

return [{
  json: {
    delivery: 'log_only',
    reason: 'Transient upstream failure; the next scheduled run is expected to succeed.',
    escalate_if: 'the same category recurs within repeat_window',
    repeat_window: '24h',
    alert: a
  }
}];
